using Godot;
using System;
using System.Collections.Generic;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class TimelinePhysicsOperations
{
    private static readonly string[] PowderFields={"points","velocities","powder_ids","powder_radii","powder_masses","powder_birth_times","powder_birth_positions","powder_sources","powder_compaction","powder_sleep","powder_contacts","powder_phase","powder_settle"};
    private static T[] JoinPrefix<T>(T[] left,T[] right,int count){var result=new T[count];Array.Copy(left,result,Math.Min(left.Length,count));if(count>left.Length)Array.Copy(right,left.Length,result,left.Length,count-left.Length);return result;}
    private static Variant PackedPrefix(Variant left,Variant right,int count)=>right.VariantType switch{Variant.Type.PackedVector3Array=>Variant.From(JoinPrefix(left.AsVector3Array(),right.AsVector3Array(),count)),Variant.Type.PackedInt32Array=>Variant.From(JoinPrefix(left.AsInt32Array(),right.AsInt32Array(),count)),Variant.Type.PackedFloat32Array=>Variant.From(JoinPrefix(left.AsFloat32Array(),right.AsFloat32Array(),count)),Variant.Type.PackedFloat64Array=>Variant.From(JoinPrefix(left.AsFloat64Array(),right.AsFloat64Array(),count)),Variant.Type.PackedByteArray=>Variant.From(JoinPrefix(left.AsByteArray(),right.AsByteArray(),count)),_=>throw new InvalidOperationException("Unsupported physics packed field: "+right.VariantType)};
    public void interpolate_points(Settings result,Settings left,Settings right,double fraction)
    {
        GD.Load<GDScript>("res://scripts/actors/fog/fog_motion_bridge.gd").Call("interpolate",result,left,right,fraction);GD.Load<GDScript>("res://scripts/actors/physics/destruction/destruction_bridge.gd").Call("interpolate",result,left,right,fraction);if(left.ContainsKey("structural"))result["structural"]=left["structural"].AsGodotDictionary().Duplicate(true);if(left.ContainsKey("destruction_events"))result["destruction_events"]=left["destruction_events"].AsGodotArray().Duplicate(true);else result.Remove("destruction_events");float weight=(float)fraction;
        if(right.ContainsKey("powder_ids")&&!left.ContainsKey("powder_ids")){foreach(string key in PowderFields)result[key]=PackedPrefix(right[key],right[key],0);result["initialized"]=false;}
        else if(left.ContainsKey("powder_ids")){foreach(string key in new[]{"powder_deposits","powder_cells","powder_inventory","powder_releases","powder_cleared"})if(left.TryGetValue(key,out var value))result[key]=value.VariantType==Variant.Type.Dictionary?Variant.From(value.AsGodotDictionary().Duplicate(true)):value;foreach(string key in PowderFields)result[key]=PackedCopy(left[key]);var points=left["points"].AsVector3Array();var next=right["points"].AsVector3Array();if(next.Length<points.Length||!Mathf.IsEqualApprox(left["initial_time"].AsDouble(),right["initial_time"].AsDouble())){result["initialized"]=left["initialized"];result["powder_time"]=left["powder_time"];result["powder_bonds"]=left["powder_bonds"].AsGodotDictionary().Duplicate(true);return;}double time=Mathf.Lerp(left["powder_time"].AsDouble(),right["powder_time"].AsDouble(),fraction);for(int i=0;i<points.Length;i++)points[i]=points[i].Lerp(next[i],weight);int count=points.Length;var births=right["powder_birth_times"].AsFloat64Array();while(count<next.Length&&births[count]<=time+1e-8)count++;foreach(string key in PowderFields)result[key]=PackedPrefix(left[key],right[key],count);result["points"]=JoinPrefix(points,next,count);result["powder_time"]=time;}
        else if(left.ContainsKey("fluid_ids")){foreach(string key in new[]{"points","velocities","fluid_ids","fluid_masses","fluid_foam","fluid_density"})result[key]=PackedCopy(left[key]);var indices=new Dictionary<long,int>();var rightIds=right["fluid_ids"].AsInt32Array();for(int i=0;i<rightIds.Length;i++)indices[rightIds[i]]=i;var ids=left["fluid_ids"].AsInt32Array();var points=left["points"].AsVector3Array();var next=right["points"].AsVector3Array();var foam=left["fluid_foam"].AsFloat32Array();var nextFoam=right["fluid_foam"].AsFloat32Array();for(int i=0;i<points.Length;i++)if(indices.TryGetValue(ids[i],out int j)){points[i]=points[i].Lerp(next[j],weight);foam[i]=Mathf.Lerp(foam[i],nextFoam[j],weight);}result["points"]=points;result["fluid_foam"]=foam;}
        else{var points=left["points"].AsVector3Array();var next=right["points"].AsVector3Array();if(points.Length==next.Length){for(int i=0;i<points.Length;i++)points[i]=points[i].Lerp(next[i],weight);result["points"]=points;}}
    }
    private Settings BlendBake(Settings left,Settings right,double fraction,bool duplicateLeft){var result=snapshot(new Settings{["value"]=left})["value"].AsGodotDictionary();result["pose"]=left["pose"].AsTransform3D().InterpolateWith(right["pose"].AsTransform3D(),(float)fraction);interpolate_points(result,duplicateLeft?result.Duplicate(true):left,right,fraction);var bones=result["bones"].AsGodotDictionary();var rightBones=right["bones"].AsGodotDictionary();foreach(var name in bones.Keys)if(rightBones.ContainsKey(name)){var bone=bones[name].AsGodotDictionary();bone["pose"]=bone["pose"].AsTransform3D().InterpolateWith(rightBones[name].AsGodotDictionary()["pose"].AsTransform3D(),(float)fraction);}return result;}
    public Settings baked(RefCounted owner,Settings bake,double time)
    {
        if(Get(bake,"portable",false).AsBool()){var actor=Model(owner)!.Call("actor_for_id",Get(bake,"owner","")).As<Resource>();var clip=actor!=null?Model(owner)!.Call("clip_for_actor_id",actor.Get("id")).As<Resource>():null;var editing=GD.Load<GDScript>("res://scripts/actors/physics/destruction/bake_editing.gd");if(actor==null||clip==null||Get(bake,"portable_authored","").AsString()!=editing.Call("portable_signature",actor).AsString()){warn(owner,"Reusable bake has physical edits; recalculate the interacting group.");return new Settings();}var source=bake.Duplicate();source["portable"]=false;source["signature"]=owner.Get("signature");source["actor"]=bake["source_actor"];var value=baked(owner,source,editing.Call("portable_time",bake,clip,time).AsDouble());if(value.Count==0)return value;string root=Get(bake,"portable_root","").AsString();var offset=root.Length>0?animated_world(owner,root,time,true,new Settings()):Transform3D.Identity;return editing.Call("portable_state",value,bake,clip,offset).AsGodotDictionary();}
        if(Get(bake,"signature","").AsString()!=owner.Get("signature").AsString()||time<Get(bake,"from",double.PositiveInfinity).AsDouble()||time>Get(bake,"to",double.NegativeInfinity).AsDouble())return new Settings();var cache=Get(bake,"cache").AsGodotObject() as Resource;if(ActorDataOperations.ScriptIs(cache,"res://scripts/actors/physics/destruction/physics_bake_cache.gd")){int count=cache!.Get("count").AsInt32();double exact=Math.Clamp((time-bake["from"].AsDouble())*bake["rate"].AsDouble(),0,count-1);int index=(int)Math.Floor(exact);var left=Get(cache.Call("frame",index).AsGodotDictionary(),bake["actor"].AsString(),new Settings()).AsGodotDictionary();string error=cache.Get("error").AsString();var right=Get(cache.Call("frame",Math.Min(index+1,count-1)).AsGodotDictionary(),bake["actor"].AsString(),new Settings()).AsGodotDictionary();if(error.Length>0)warn(owner,error);error=cache.Get("error").AsString();if(error.Length>0)warn(owner,error);if(left.Count==0||right.Count==0)return new Settings();double fraction=exact-index;if(index==count-2){double start=bake["from"].AsDouble()+index/bake["rate"].AsDouble(),end=Math.Min(bake["to"].AsDouble(),start+1/bake["rate"].AsDouble());fraction=Math.Clamp((time-start)/Math.Max(.000001,end-start),0,1);}return BlendBake(left,right,fraction,false);}
        var frames=Get(bake,"frames",new GArray()).AsGodotArray();if(frames.Count==0)return new Settings();double at=Math.Clamp((time-bake["from"].AsDouble())*bake["rate"].AsDouble(),0,frames.Count-1);int frame=(int)Math.Floor(at);var nextFrame=frames[Math.Min(frame+1,frames.Count-1)].AsGodotDictionary();if(nextFrame.ContainsKey("powder_ids")&&!nextFrame.ContainsKey("powder_phase"))nextFrame=snapshot(new Settings{["value"]=nextFrame})["value"].AsGodotDictionary();return BlendBake(frames[frame].AsGodotDictionary(),nextFrame,at-frame,true);
    }
}
